import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    """Exact R(f) for step function h."""
    s = h.sum()
    if s <= 0.0:
        return -1.0
    L = np.convolve(h, h)
    n = L.size
    Lf = np.empty(n + 2)
    Lf[0] = 0.0
    Lf[-1] = 0.0
    Lf[1:-1] = L
    a = Lf[:-1]
    b = Lf[1:]
    L2sq = (a * a + a * b + b * b).sum() / 3.0
    m = L.max()
    if m <= 0.0:
        return -1.0
    return L2sq / (s * s * m)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.5

    best = None
    best_r = -1.0

    def consider(h):
        nonlocal best, best_r
        h = np.maximum(np.asarray(h, float), 0.0)
        if h.sum() <= 0.0:
            return
        r = _R(h)
        if r > best_r:
            best_r = r
            best = h.copy()

    def opt(h0, maxiter, method='L-BFGS-B'):
        if time.process_time() > deadline:
            return
        h0 = np.maximum(np.asarray(h0, float), 0.0)
        n = h0.size
        if n == 0:
            return

        def negR(x):
            return -_R(np.maximum(x, 0.0))

        try:
            if method == 'L-BFGS-B':
                res = minimize(negR, h0, method=method,
                               bounds=[(0.0, None)] * n,
                               options={'maxiter': maxiter, 'ftol': 1e-15,
                                        'gtol': 1e-11, 'maxfun': 200000})
            else:
                res = minimize(negR, h0, method=method,
                               options={'maxiter': maxiter,
                                        'xtol': 1e-10, 'ftol': 1e-14})
            consider(res.x)
        except Exception:
            pass

    # ---- build candidate starting shapes -----------------------------------
    def shapes_for_n(n):
        x = np.linspace(-1.0, 1.0, n)
        out = []
        out.append(np.exp(-3.0 * x * x))
        out.append(np.exp(-1.2 * x * x))
        out.append(np.exp(-6.0 * x * x))
        out.append(np.clip(1.5 - x * x, 0.0, None))
        out.append(np.ones(n))
        out.append(0.5 + 0.5 * np.cos(np.pi * x))
        out.append(1.0 / (1.0 + 3.0 * x * x))
        out.append(np.clip(1.0 - np.abs(x), 0.0, None))
        # plateau-ish: super-gaussian
        out.append(np.exp(-(x * x) ** 2 * 4.0))
        return out

    cands = []
    if start is not None:
        cands.append(np.asarray(start, float))

    # ---- first pass: optimize each candidate at moderate N -----------------
    for n in [60, 80, 120, 160]:
        if time.process_time() > deadline:
            break
        for c in shapes_for_n(n):
            if time.process_time() > deadline:
                break
            opt(np.maximum(c, 1e-6), 500)

    # ---- refine the best ---------------------------------------------------
    for _ in range(40):
        if time.process_time() > deadline or best is None:
            break
        opt(best, 1500)

    # ---- try upsampling the best to finer grids and re-optimize -----------
    if best is not None:
        for n2 in [100, 140, 200, 260]:
            if time.process_time() > deadline:
                break
            xi = np.linspace(0.0, 1.0, best.size)
            xj = np.linspace(0.0, 1.0, n2)
            h2 = np.interp(xj, xi, best)
            opt(np.maximum(h2, 1e-6), 400)
            if best is not None and best.size != n2:
                # keep refining the upsampled version
                opt(best, 800)

    # ---- final derivative-free polish on the best -------------------------
    if best is not None and best.size <= 130:
        if time.process_time() < deadline:
            opt(best, 2000, method='Powell')

    if best is None:
        best = np.ones(50)
    return np.maximum(best, 0.0)

import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    a = np.empty(len(L) + 1)
    b = np.empty(len(L) + 1)
    a[0] = 0.0
    a[1:] = L
    b[:-1] = L
    b[-1] = 0.0
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    inf = L.max()
    if inf <= 0:
        return 0.0
    return l2sq / (s * s * inf)


def _smooth_init(n, kind):
    x = np.linspace(0.0, 1.0, n)
    if kind == 0:
        return np.ones(n)
    if kind == 1:
        return 1.0 - np.abs(2.0 * x - 1.0)  # triangle
    if kind == 2:
        return np.clip(1.0 - (2.0 * x - 1.0) ** 2, 0, None)
    if kind == 3:
        # flat-topped smoothed indicator (logistic-like)
        return 1.0 / (1.0 + np.exp(-20.0 * (x - 0.5) * (1.0 - x) * 4.0))
    if kind == 4:
        return np.exp(-6.0 * (x - 0.5) ** 2)
    return np.ones(n)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best = np.maximum(best, 0.0)
        if best.size == 0 or best.sum() <= 0:
            best = np.ones(50)
    else:
        best = np.ones(50)
    best_r = _R(best)

    rng = np.random.default_rng(20240607)

    # Coordinate ascent: repeatedly pick a coordinate and try to improve it.
    def coord_ascent(h, r, max_evals, coord_step):
        n = len(h)
        evals = 0
        improved_any = False
        order = rng.permutation(n)
        idx = 0
        while evals < max_evals and time.process_time() < deadline:
            i = int(order[idx % n])
            idx += 1
            if idx % n == 0:
                order = rng.permutation(n)
            old = h[i]
            # try a few step sizes
            for _ in range(3):
                if evals >= max_evals or time.process_time() >= deadline:
                    break
                new_val = max(0.0, old + coord_step * (rng.standard_normal()))
                if new_val == old:
                    continue
                h[i] = new_val
                if h.sum() <= 0:
                    h[i] = old
                    evals += 1
                    continue
                nr = _R(h)
                evals += 1
                if nr > r:
                    r = nr
                    old = new_val
                    improved_any = True
                else:
                    h[i] = old
        return r, improved_any

    # Phase 1: try various N and shapes
    Ns = [len(best)]
    for n in [20, 30, 40, 50, 64, 80, 100, 128, 160, 200, 256, 320,
              400, 500, 640, 800, 1000, 1280, 1600, 2000, 2500, 3200,
              4000, 5000, 6400]:
        Ns.append(n)

    for n in Ns:
        if time.process_time() >= deadline:
            break
        for kind in range(5):
            if time.process_time() >= deadline:
                break
            h = _smooth_init(n, kind).astype(float)
            if h.sum() <= 0:
                continue
            r = _R(h)
            # quick coordinate ascent
            r, _ = coord_ascent(h, r, max(50, 4000 // max(1, n // 32)), 0.2)
            if r > best_r:
                best_r = r
                best = h.copy()

    # Phase 2: refine best with coordinate ascent, decreasing step
    cur = best.copy()
    cur_r = best_r
    step = 0.15
    while time.process_time() < deadline and step > 1e-4:
        cur_r, improved = coord_ascent(cur, cur_r, max(200, len(cur) * 8), step)
        if cur_r > best_r:
            best_r = cur_r
            best = cur.copy()
        if not improved:
            step *= 0.6
        else:
            step *= 0.95
            cur = best.copy()
            cur_r = best_r

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)
    return best

