import time
from scipy.optimize import minimize


def _R(h):
    """Exact R(f) for step function h."""
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0.0:
        return -1.0
    L = np.convolve(h, h)
    n = L.size
    Lf = np.empty(n + 2)
    Lf[0] = 0.0
    Lf[-1] = 0.0
    Lf[1:-1] = L
    a = Lf[:-1]
    b = Lf[1:]
    L2sq = (a * a + a * b + b * b).sum() / 3.0
    m = L.max()
    if m <= 0.0:
        return -1.0
    return L2sq / (s * s * m)


def _resample(h, n):
    """Resample a step function to n steps, preserving total mass."""
    h = np.asarray(h, dtype=float)
    if h.size == n:
        return h.copy()
    # cumulative integral -> interpolate at new grid boundaries
    edges_old = np.linspace(0.0, 1.0, h.size + 1)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    total = cum[-1]
    edges_new = np.linspace(0.0, 1.0, n + 1)
    cum_new = np.interp(edges_new, edges_old, cum)
    h2 = np.diff(cum_new)
    h2 = np.maximum(h2, 0.0)
    if h2.sum() > 0:
        h2 *= total / h2.sum()
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0

    def consider(h):
        nonlocal best, best_r
        h = np.maximum(np.asarray(h, float).ravel(), 0.0)
        if h.size == 0 or h.size > 50000 or h.sum() <= 0.0:
            return
        r = _R(h)
        if r > best_r:
            best_r = r
            best = h.copy()

    def opt(h0, maxiter, method='L-BFGS-B'):
        if time.process_time() > deadline:
            return
        h0 = np.maximum(np.asarray(h0, float), 0.0)
        n = h0.size
        if n == 0:
            return

        # Normalize scale for numerical stability
        s = h0.sum()
        if s <= 0:
            return
        h0 = h0 * (1.0 / s) * n

        def negR(x):
            return -_R(np.maximum(x, 0.0))

        try:
            if method == 'L-BFGS-B':
                res = minimize(negR, h0, method=method,
                               bounds=[(0.0, None)] * n,
                               options={'maxiter': maxiter, 'ftol': 1e-16,
                                        'gtol': 1e-12, 'maxfun': 400000,
                                        'maxcor': 30})
            else:
                res = minimize(negR, h0, method=method,
                               options={'maxiter': maxiter,
                                        'xtol': 1e-11, 'ftol': 1e-15})
            consider(res.x)
        except Exception:
            pass

    def shapes_for_n(n):
        x = np.linspace(-1.0, 1.0, n)
        return [
            np.exp(-3.0 * x * x),
            np.exp(-1.2 * x * x),
            np.exp(-6.0 * x * x),
            np.clip(1.5 - x * x, 0.0, None),
            np.ones(n),
            0.5 + 0.5 * np.cos(np.pi * x),
            1.0 / (1.0 + 3.0 * x * x),
            np.clip(1.0 - np.abs(x), 0.0, None),
            np.exp(-(x * x) ** 2 * 4.0),
            np.exp(-(np.abs(x) ** 1.5) * 3.0),
            np.clip(1.0 - x * x, 0.0, None) ** 0.5,
        ]

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 50000 and np.all(np.isfinite(s)) and s.sum() > 0:
            consider(s)

    # ---- first pass: optimize each candidate at moderate N -----------------
    for n in [60, 80, 120, 160]:
        if time.process_time() > deadline:
            break
        for c in shapes_for_n(n):
            if time.process_time() > deadline:
                break
            opt(np.maximum(c, 1e-6), 500)

    # ---- refine the best ---------------------------------------------------
    for _ in range(40):
        if time.process_time() > deadline or best is None:
            break
        opt(best, 1500)

    # ---- multi-scale refinement: resample best to several N and re-opt ----
    if best is not None:
        base = best.copy()
        for n2 in [72, 96, 112, 128, 144, 176, 208, 240, 288]:
            if time.process_time() > deadline:
                break
            h2 = _resample(base, n2)
            opt(np.maximum(h2, 1e-6), 600)
            if best is not None and best.size != n2:
                opt(best, 800)
            if best is not None and best.size > n2:
                # also try downsampled version of current best
                opt(np.maximum(_resample(best, n2), 1e-6), 400)

    # ---- targeted local polish on current best at its own N --------------
    if best is not None:
        n = best.size
        for _ in range(30):
            if time.process_time() > deadline:
                break
            opt(best, 1200)

    # ---- final derivative-free polish ------------------------------------
    if best is not None and best.size <= 200:
        if time.process_time() < deadline:
            opt(best, 2500, method='Powell')

    if best is None:
        best = np.ones(80)
    return np.maximum(best, 0.0)

