def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    mx = L.max()
    if mx <= 0:
        return -1.0
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    return num / (s * s * mx)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    if h.size == N:
        return h.copy()
    x = np.linspace(0, 1, h.size)
    xn = np.linspace(0, 1, N)
    return np.interp(xn, x, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def oot():
        return time.process_time() >= deadline

    best = None
    best_r = -1.0

    def consider(h):
        nonlocal best, best_r
        h = np.asarray(h, dtype=float).ravel()
        if h.size == 0 or h.size > 50000 or not np.all(np.isfinite(h)):
            return
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            return
        r = _R(h)
        if r > best_r:
            best_r = r
            best = h.copy()

    if start is not None:
        consider(start)

    # Structured candidates including flat-top / near-parabolic shapes
    cands = []
    for N in (30, 38, 50, 70, 100, 150, 200):
        x = np.linspace(-1, 1, N)
        cands.append(np.maximum(0.0, 1.0 - x * x))
        cands.append(0.5 * (1.0 + np.cos(np.pi * x)))
        cands.append(np.exp(-4.0 * x * x))
        for frac in (0.2, 0.35, 0.5):
            c = np.ones(N)
            k = max(1, int(frac * N / 2))
            e = np.linspace(0, 1, k + 2)[1:-1]
            c[:k] = e ** 2
            c[N - k:] = e[::-1] ** 2
            cands.append(c)
    cands.append(np.ones(50))
    for c in cands:
        consider(c)

    if best is None:
        best = np.ones(50)
        best_r = _R(best)

    rng = np.random.default_rng(20240607)

    # Resample start to nearby lengths
    if start is not None:
        base = np.asarray(start, dtype=float).ravel()
        for N in range(max(3, base.size - 12), min(400, base.size + 25)):
            if oot():
                break
            consider(_resample(base, N))

    # Smooth optimizer: softplus parametrization, L-BFGS-B, multiple N.
    def sp(z):
        return np.logaddexp(0.0, z)

