        h = np.maximum(h, 1e-9)
        return np.where(h > 30.0, h, np.log(np.expm1(np.minimum(h, 30.0)) + 1e-12))

    Ns = sorted(set([best.size] + [38, 50, 60, 80, 100, 150, 200]))
    phase1_end = t0 + budget_seconds * 0.55

    while time.process_time() < phase1_end:
        for N in Ns:
