import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0.0:
        return -1.0
    L = np.convolve(h, h)
    n = L.size
    Lf = np.empty(n + 2)
    Lf[0] = 0.0
    Lf[-1] = 0.0
    Lf[1:-1] = L
    a = Lf[:-1]
    b = Lf[1:]
    L2sq = (a * a + a * b + b * b).sum() / 3.0
    m = L.max()
    if m <= 0.0:
        return -1.0
    return L2sq / (s * s * m)


def _resample(h, n):
    h = np.asarray(h, dtype=float)
    if h.size == n:
        return h.copy()
    edges_old = np.linspace(0.0, 1.0, h.size + 1)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    total = cum[-1]
    edges_new = np.linspace(0.0, 1.0, n + 1)
    cum_new = np.interp(edges_new, edges_old, cum)
    h2 = np.diff(cum_new)
    h2 = np.maximum(h2, 0.0)
    if h2.sum() > 0:
        h2 *= total / h2.sum()
    return h2


