                break
            h2 = _resample(base, n2)
            opt(np.maximum(h2, 1e-6), 600)
            if best is not None and best.size != n2:
                opt(best, 800)
            if best is not None and best.size > n2:
                opt(np.maximum(_resample(best, n2), 1e-6), 400)

    # ---- targeted local polish on current best at its own N --------------
    if best is not None:
        for _ in range(30):
            if time.process_time() > deadline:
                break
            opt(best, 1200)

    # ---- final derivative-free polish ------------------------------------
    if best is not None and best.size <= 200:
        if time.process_time() < deadline:
            opt(best, 2500, method='Powell')

    if best is None:
        best = np.ones(80)
    return np.maximum(best, 0.0)

