import time
from scipy.optimize import minimize


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    Lp = np.concatenate(([0.0], L, [0.0]))
    quad = np.sum(Lp[:-1] ** 2 + Lp[:-1] * Lp[1:] + Lp[1:] ** 2) / 3.0
    inf = L.max()
    if inf <= 0:
        return 0.0
    return quad / (s * s * inf)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80
    rng = np.random.default_rng(2024)

    best = None
    best_r = -1.0

    seeds = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 50000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seeds.append(s.copy())
    for N in (30, 50, 80, 120, 200):
        x = np.linspace(-1, 1, N)
        seeds.append(np.maximum(0.0, 1.0 - x * x))
        seeds.append(np.exp(-3.0 * x * x))
        seeds.append(np.ones(N))
    for c in seeds:
        r = R_of(c)
        if r > best_r:
            best_r, best = r, c.copy()

    def sp(z):
        return np.logaddexp(0.0, z)

    def negR_from_z(z):
        return -R_of(sp(z))

    Ns = [best.size] + [30, 40, 50, 60, 80, 120]
    tried = set()
    while time.process_time() < deadline:
        for N in Ns:
            if time.process_time() >= deadline:
                break
            if N in tried and rng.random() < 0.6:
                continue
            tried.add(N)
            if best.size == N:
                h0 = best.copy()
            else:
                h0 = np.interp(np.linspace(0, 1, N),
                               np.linspace(0, 1, best.size), best)
            h0 = np.maximum(h0, 1e-6)
            h0 = h0 * (1.0 + 0.1 * rng.standard_normal(N))
            h0 = np.maximum(h0, 1e-6)
            z0 = np.log(np.expm1(np.minimum(h0, 50.0)) + 1e-9)
            z0 = np.clip(z0, -5.0, 5.0)

            try:
                res = minimize(negR_from_z, z0, method='L-BFGS-B',
                               options={'maxiter': 300, 'ftol': 1e-12, 'gtol': 1e-10})
                h = sp(res.x)
            except Exception:
                continue
            if h.sum() <= 0:
                continue
            r = R_of(h)
            if r > best_r:
                best_r, best = r, h.copy()

    # Fine coordinate-wise refinement with shrinking step
    cur = best.copy()
    cur_r = R_of(cur)
    step = 0.05 * (cur.max() + 1e-9)
    while time.process_time() < deadline:
        improved = False
        order = rng.permutation(cur.size)
        for i in order:
            if time.process_time() >= deadline:
                break
            old = cur[i]
            for d in (step, -step, step * 0.5, -step * 0.5):
                cur[i] = max(0.0, old + d)
                r = R_of(cur)
                if r > cur_r:
                    cur_r = r
                    improved = True
                    break
                cur[i] = old
        if not improved:
            step *= 0.5
            if step < 1e-9:
                break
    if cur_r > best_r:
        best, best_r = cur, cur_r

    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _L2(h):
    s = h.sum()
    if s <= 0:
        return 0.0, 0.0
    L = np.convolve(h, h)
    a = np.empty(L.size + 1)
    b = np.empty(L.size + 1)
    a[0] = 0.0; a[1:] = L
    b[:-1] = L; b[-1] = 0.0
    q = np.sum(a * a + a * b + b * b) / 3.0
    inf = L.max()
    return q, inf


def _R(h):
    q, inf = _L2(h)
    s = h.sum()
    if s <= 0 or inf <= 0:
        return -1.0
    return q / (s * s * inf)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    if start is not None:
        best = np.maximum(np.asarray(start, dtype=float).ravel().copy(), 0.0)
        if best.size == 0 or best.sum() <= 0:
            best = np.ones(30)
    else:
        best = np.ones(30)
    best_r = _R(best)
    best = best / best.max()

    rng = np.random.default_rng(424242)

    def consider(h):
        nonlocal best, best_r
        h = np.asarray(h, dtype=float).ravel()
        if h.size == 0 or h.size > 50000:
            return
        if not np.all(np.isfinite(h)):
            return
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            return
        r = _R(h)
        if r > best_r:
            best_r = r
            best = h.copy()

    # Softplus parametrization for a smooth, nonneg optimization.
    def sp(z):
        return np.logaddexp(0.0, z)

    def to_z(h):
        h = np.maximum(h, 1e-9)
        return np.where(h > 30.0, h, np.log(np.expm1(np.minimum(h, 30.0)) + 1e-12))

    def negR(z):
        return -_R(sp(z))

    def polish(h):
        # L-BFGS-B on softplus params, then coordinate polish.
        h = np.maximum(h, 1e-9)
        h = h / h.max()
        z0 = np.clip(to_z(h), -8.0, 8.0)
        try:
            res = minimize(negR, z0, method='L-BFGS-B',
                           options={'maxiter': 400, 'ftol': 1e-14,
                                    'gtol': 1e-12, 'maxls': 50})
            consider(sp(res.x))
        except Exception:
            pass
        # coordinate polish
        cur = best.copy()
        cur_r = best_r
        step = 0.05 * (cur.max() + 1e-9)
        for _ in range(60):
            if time.process_time() > deadline:
                break
            improved = False
            for i in rng.permutation(cur.size):
                if time.process_time() > deadline:
                    break
                old = cur[i]
                for d in (step, -step, step * 0.5, -step * 0.5):
                    cur[i] = max(0.0, old + d)
                    r = _R(cur)
                    if r > cur_r:
                        cur_r = r
                        improved = True
                        break
                    cur[i] = old
            if not improved:
                step *= 0.5
                if step < 1e-10:
                    break
        consider(cur)

    def seeds(n):
        x = np.linspace(-1, 1, n)
        out = [np.ones(n),
               np.exp(-2.0 * x * x),
               np.exp(-1.0 * x * x),
               np.exp(-3.0 * x * x),
               np.clip(1.0 - x * x, 0, None),
               np.clip(1.0 - np.abs(x), 0, None) + 0.01,
               1.0 / (1.0 + np.exp(-8.0 * (0.5 - np.abs(x)))),
               np.cos(0.5 * np.pi * x) ** 2]
        return out

    # Try many small N (small N looks promising here).
    Ns = sorted(set([best.size] + list(range(8, 31)) + [35, 40, 50, 60, 80]))

    for n in Ns:
        if time.process_time() > deadline:
            break
        for c in seeds(n):
            if time.process_time() > deadline:
                break
            if c.sum() <= 0:
                continue
            cc = c.astype(float).copy()
            cc = cc / max(cc.max(), 1e-12)
            consider(cc)
            if n <= 30 or rng.random() < 0.3:
                polish(cc)

    # Final polish on best.
    polish(best)

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(30)
    return best

import numpy as np
import time


def _R(h):
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    Lf = np.empty(len(L) + 2)
    Lf[0] = 0.0
    Lf[1:-1] = L
    Lf[-1] = 0.0
    a = Lf[:-1]
    b = Lf[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return l2sq / (s * s * inf)


def _grad_R(h):
    n = len(h)
    L = np.convolve(h, h)
    s = h.sum()
    if s <= 0:
        return np.zeros(n)
    jmax = int(np.argmax(L))
    M = L[jmax]
    if M <= 0:
        return np.zeros(n)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]
    b = Lf[1:]
    q = np.sum(a * a + a * b + b * b) / 3.0
    left = Lf[:-2]
    right = Lf[2:]
    dq_dL = (left + 2 * L) / 3.0 + (2 * L + right) / 3.0
    corr = np.correlate(dq_dL, h, mode='valid')
    dq_dh = 2.0 * corr
    dM_dh = np.zeros(n)
    lo = max(0, jmax - (n - 1))
    hi = min(n - 1, jmax)
    idx = np.arange(lo, hi + 1)
    dM_dh[idx] = 2.0 * h[jmax - idx]
    denom = s * s * M
    dR = dq_dh / denom - q * (2.0 / s + dM_dh / M) / denom
    return dR


def _climb(h, deadline, max_evals, lr=0.05, patience=30):
    h = np.maximum(h.astype(float), 0.0)
    r = _R(h)
    if r <= 0:
        return h, r
    n = len(h)
    evals = 0
    no_imp = 0
    while evals < max_evals and time.process_time() < deadline:
        g = _grad_R(h)
        gn = np.linalg.norm(g)
        if gn < 1e-14:
            break
        hscale = h.mean() + 1e-12
        step = lr * hscale * g / gn * np.sqrt(n)
        improved = False
        for sc in (1.0, 0.5, 0.25, 0.1, 0.03, 0.01):
            hn = np.maximum(h + step * sc, 0.0)
            if hn.sum() <= 0:
                continue
            nr = _R(hn)
            evals += 1
            if nr > r + 1e-13:
                h = hn
                r = nr
                improved = True
                break
            if time.process_time() >= deadline:
                break
        if not improved:
            lr *= 0.6
            no_imp += 1
            if lr < 1e-8 or no_imp > patience:
                break
        else:
            no_imp = 0
    return h, r


def _coord(h, r, deadline, max_evals, step, rng):
    h = h.copy()
    n = len(h)
    evals = 0
    order = rng.permutation(n)
    idx = 0
    improved_any = False
    while evals < max_evals and time.process_time() < deadline:
        i = int(order[idx % n])
        idx += 1
        if idx % n == 0:
            order = rng.permutation(n)
        old = h[i]
        delta = step * (h.mean() + 1e-9) * rng.standard_normal()
        new_val = max(0.0, old + delta)
        if new_val == old:
            continue
        h[i] = new_val
        if h.sum() <= 0:
            h[i] = old
            evals += 1
            continue
        nr = _R(h)
        evals += 1
        if nr > r + 1e-13:
            r = nr
            improved_any = True
        else:
            h[i] = old
    return h, r, improved_any


def _run(h0, deadline, rng, budget_evals):
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    r = _R(h)
    best_h, best_r = h.copy(), r
    h, r = _climb(h, deadline, budget_evals, lr=0.15)
    if r > best_r:
        best_h, best_r = h.copy(), r
    for step in (0.3, 0.15, 0.07, 0.03, 0.015):
        if time.process_time() >= deadline:
            break
        h, r, imp = _coord(h, r, deadline, max(200, len(h) * 6), step, rng)
        if r > best_r:
            best_h, best_r = h.copy(), r
        if not imp and step < 0.03:
