    if r > best_r:
        best_h, best_r = h.copy(), r
    for step in (0.3, 0.15, 0.07, 0.03, 0.015):
        if time.process_time() >= deadline:
            break
        h, r, imp = _coord(h, r, deadline, max(200, len(h) * 6), step, rng)
        if r > best_r:
            best_h, best_r = h.copy(), r
        if not imp and step < 0.03:
            break
    if time.process_time() < deadline:
        h, r = _climb(best_h.copy(), deadline, budget_evals // 2, lr=0.03)
        if r > best_r:
            best_h, best_r = h.copy(), r
    return best_h, best_r


def _refine_support(h, r, deadline, rng, new_n):
    n = len(h)
    if new_n <= 0 or new_n == n:
        return h, r
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, new_n)
    hn = np.interp(x_new, x_old, h)
    hn = np.maximum(hn, 0.0)
    if hn.sum() <= 0:
        return h, r
    return _run(hn, deadline, rng, 3000)


def _smooth(h, k):
    """Box-smooth heights with window k, preserving support."""
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    # fix edges (divide out the partial-window effect)
    w = np.convolve(np.ones_like(h), ker, mode='same')
    return hs / np.maximum(w, 1e-12)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    rng = np.random.default_rng(20240607)

    if start is not None:
        best = np.maximum(np.asarray(start, dtype=float).ravel().copy(), 0.0)
        if best.size == 0 or best.sum() <= 0:
            best = np.ones(12)
    else:
        best = np.ones(12)
    best_r = _R(best)

    # Phase 0: heavily refine start.
    if time.process_time() < deadline:
        h, r = _run(best, deadline, rng, 8000)
        if r > best_r:
            best, best_r = h, r

    # Phase 1: multi-start over small N with diverse shapes.
    Ns = [6, 7, 8, 9, 10, 11, 12, 13, 14, 16, 18, 20, 24, 28, 32, 40, 50]

    def shapes(n):
        x = np.linspace(-1, 1, n)
        return [
            np.ones(n),
            np.exp(-2.0 * x * x),
            np.exp(-1.0 * x * x),
            np.exp(-4.0 * x * x),
            np.clip(1.0 - x * x, 0, None) + 1e-3,
            np.clip(1.0 - np.abs(x), 0, None) + 1e-3,
            1.0 / (1.0 + np.exp(-10.0 * (0.6 - np.abs(x)))),
            np.sin(np.pi * (x + 1) / 2.0) ** 2 + 1e-3,
            np.exp(-0.5 * (x / 0.4) ** 2),
            np.cos(np.pi * x / 2.0) ** 2 + 1e-3,
        ]

    for n in Ns:
        if time.process_time() >= deadline:
            break
        for c in shapes(n):
            if time.process_time() >= deadline:
                break
            if c.sum() <= 0:
                continue
            h, r = _climb(c.astype(float).copy(), deadline, 2000, lr=0.2)
            if r > best_r - 0.02:
                h, r = _run(h, deadline, rng, 2500)
            if r > best_r:
                best, best_r = h.copy(), r

    # Phase 1b: resample the current best to nearby sizes and polish.
    for dn in (-2, -1, 1, 2, 3):
        if time.process_time() >= deadline:
            break
        new_n = len(best) + dn
        if 3 <= new_n <= 60:
            h, r = _refine_support(best, best_r, deadline, rng, new_n)
            if r > best_r:
                best, best_r = h, r

    # Phase 2: alternating polish on best, decreasing step.
    cur = best.copy()
    cur_r = best_r
    step = 0.2
    for _ in range(60):
        if time.process_time() >= deadline:
            break
        cur, cur_r = _climb(cur, deadline, 4000, lr=0.05)
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline:
            break
        cur, cur_r, imp = _coord(cur, cur_r, deadline, max(400, len(cur) * 10), step, rng)
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if not imp:
            step *= 0.5
            if step < 1e-6:
                break
            cur = best.copy()
            cur_r = best_r

    # Phase 3: perturbed restarts from best.
    for _ in range(40):
        if time.process_time() >= deadline:
            break
        pert = best * np.exp(0.12 * rng.standard_normal(len(best)))
        pert = np.maximum(pert, 0.0)
        h, r = _run(pert, deadline, rng, 2000)
        if r > best_r:
            best, best_r = h.copy(), r

    # Phase 4: multi-scale resample + polish of best.
    for new_n in (len(best) + 1, len(best) - 1, len(best) + 2, 2 * len(best),
                  max(3, len(best) // 2)):
        if time.process_time() >= deadline:
            break
        if 3 <= new_n <= 80:
            h, r = _refine_support(best, best_r, deadline, rng, new_n)
            if r > best_r:
                best, best_r = h, r

    # NEW Phase 5: smoothing-based exploration to escape narrow local maxima.
    # Smoothing the current best gives a perturbed starting point in the same
    # basin but flatter, which the polish then re-sharpens to a possibly better
    # optimum. This targets the fine structure of the optimal step function.
    for k in (2, 3, 4, 5):
        if time.process_time() >= deadline:
            break
        hs = _smooth(best, k)
        if hs.sum() <= 0:
            continue
        h, r = _run(hs, deadline, rng, 3000)
        if r > best_r:
            best, best_r = h.copy(), r

    # NEW Phase 6: random additive perturbations to escape.
    for _ in range(30):
        if time.process_time() >= deadline:
            break
        scale = 0.05 * best.mean()
        pert = best + scale * rng.standard_normal(len(best))
        pert = np.maximum(pert, 0.0)
        if pert.sum() <= 0:
            continue
        h, r = _run(pert, deadline, rng, 2000)
        if r > best_r:
            best, best_r = h.copy(), r

    # Final polish.
    if time.process_time() < deadline:
        h, r = _climb(best.copy(), deadline, 8000, lr=0.02)
        if r > best_r:
            best, best_r = h, r

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(12)
    return best

